This test uses a parent context with a 10ms deadline, so it will still time out even if the new default summary-generation timeout is removed. That means it doesn’t actually verify the behavior introduced in this PR (the default timeout applied when callers pass a context without a deadline). Consider refactoring production code to allow injecting the timeout duration (or only applying the default when no deadline is set) so the default-timeout behavior can be tested deterministically.
```suggestion
func TestGenerateFromTranscript_ContextCanceled(t *testing.T) {
	t.Parallel()

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	timer := time.AfterFunc(10*time.Millisecond, cancel)
	defer timer.Stop()

	transcript := []byte(`{"type":"user","message":{"content":"Hello"}}`)
	start := time.Now()
	_, err := GenerateFromTranscript(ctx, transcript, nil, "", &blockingGenerator{wait: make(chan struct{})})
	if err == nil {
		t.Fatal("expected cancellation error")
	}
	if !strings.Contains(err.Error(), "canceled") {
		t.Fatalf("unexpected error: %v", err)
	}
	if elapsed := time.Since(start); elapsed > time.Second {
		t.Fatalf("cancellation took too long: %s", elapsed)
